//! Release metadata, update decision, and check scheduling (task
//! 2026-11-11_auto-update). Owns the `release.yaml` contract: fetch plumbing,
//! parsing, platform target mapping, the "is an update available" rule, the
//! next-check deadline, and the background check thread hand-off. The install
//! flow lives in `update::install` (Stage 4); UI reactions in `gui` (Stage 6);
//! startup scheduling in `main` (Stage 7).
//!
//! Metadata format: the asset is generated by `scripts/package-release.sh` as
//! YAML (`key: value`, block sequence under `files:`) and ships under a
//! `.yaml` name. Strict `toml::from_str` rejects it ("key with no value"), so
//! [`parse_manifest`] deserializes with the locked `serde-saphyr` crate —
//! Stage 3 amendment, approved by the user 2026-11-11: a direct declaration
//! of the crate `rust-i18n` already locks transitively (via
//! `rust-i18n-macro` → `rust-i18n-support`), zero new packages, replacing the
//! earlier hand-rolled YAML-subset parser.
//!
//! Update decision (stage 11 sub-item 1, task 2026-11-11_auto-update): the
//! triggers are the release DATE (newer than the local build time) and the
//! release VERSION (higher than the local version). Hotfix 2026-11-12: an
//! equal `commit_sha` SUPPRESSES the date trigger — `releaseDate` is the
//! packaging timestamp of `scripts/package-release.sh`, not a commit
//! timestamp, so a re-packaged nightly of the SAME commit carries a date
//! newer than the local build time and used to announce a phantom update.
//! The sha stays in the manifest and the dialog summary; the version trigger
//! keeps its semantics under the guard. The RFC 3339 timestamps are parsed by
//! a hand-written [`parse_rfc3339_epoch_seconds`] (no new dependency),
//! compared as Unix seconds.

pub(crate) mod install;
pub(crate) mod notes;

use std::sync::mpsc;
use std::time::Duration;
use std::time::Instant;

use crate::config;

/// Whole-request budget for a metadata fetch, from DNS to the last body byte;
/// it continues across redirects (ureq `timeout_global`).
const FETCH_TIMEOUT: Duration = Duration::from_secs(10);

/// GitHub redirects this download URL to the release asset storage, so the
/// agent must follow redirects (default, cap below).
const STABLE_MANIFEST_URL: &str =
    "https://github.com/Apkawa/virshot/releases/latest/download/release.yaml";

/// The rolling `nightly` prerelease: assets are replaced in place and the tag
/// target moves per build, so this URL always carries the newest metadata.
const NIGHTLY_MANIFEST_URL: &str =
    "https://github.com/Apkawa/virshot/releases/download/nightly/release.yaml";

/// Metadata/transport failures, typed per module (`thiserror` enum). `Clone`
/// so one outcome can be logged and surfaced as a toast from the same value.
#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
pub(crate) enum UpdateError {
    /// The request itself failed: DNS/TLS/timeout/transport error from ureq,
    /// or the body could not be read. Carries the crate's error message.
    #[error("failed to fetch release metadata: {0}")]
    Fetch(String),

    /// The server answered a non-2xx status. Data, not a crash: a `stable`
    /// channel before any stable release exists is a plain 404.
    #[error("release metadata fetch returned HTTP status {0}")]
    HttpStatus(u16),

    /// The body is not parseable metadata: malformed YAML (scanner/parser
    /// error), a missing required field, a `size` that is not a plain
    /// unsigned integer, or a `releaseDate` the RFC 3339 parser cannot read.
    /// Carries the serde-saphyr message verbatim — it names the offending
    /// position itself (`at line X, column Y`); date failures name the
    /// offending value.
    #[error("invalid release metadata: {0}")]
    Parse(String),

    /// The manifest has no `files[]` entry for the requested target type —
    /// nothing may be downloaded, so no update is offered (e.g. the deferred
    /// ARM64 targets, which `release.yml` never publishes).
    #[error("release metadata has no file for target {0}")]
    NoFileForTarget(String),
}

/// One `files[]` entry of `release.yaml`. Wire names: `url`, `type`,
/// `sha512` (base64 of the raw 64-byte digest, 88 chars), `size` (bytes).
#[derive(Debug, Clone, PartialEq, Eq, serde::Deserialize)]
pub(crate) struct ReleaseFile {
    pub(crate) url: String,
    /// The wire key is `type`; `file_type` avoids the keyword-shaped name.
    #[serde(rename = "type")]
    pub(crate) file_type: String,
    pub(crate) sha512: String,
    pub(crate) size: u64,
}

/// The whole `release.yaml` asset. Wire names: `version`, `releaseDate`
/// (ISO-8601 with milliseconds and `Z`, or a `±HH:MM` offset), `commit_sha`
/// (SHORT sha — dialog summary plus the up-to-date guard of
/// [`decide_update`], hotfix 2026-11-12).
#[derive(Debug, Clone, PartialEq, Eq, serde::Deserialize)]
pub(crate) struct ReleaseManifest {
    pub(crate) version: String,
    #[serde(rename = "releaseDate")]
    pub(crate) release_date: String,
    pub(crate) commit_sha: String,
    pub(crate) files: Vec<ReleaseFile>,
}

/// Parses the `release.yaml` asset with [`serde_saphyr::from_str`]. Failure
/// modes, all [`UpdateError::Parse`] carrying the serde-saphyr message
/// verbatim: malformed YAML (scanner/parser error, which names its own
/// position), a missing required field (`version`, `releaseDate`,
/// `commit_sha`, `files`, or any field of a `files[]` entry — serde's
/// missing-field error), or a `size` that is not a plain unsigned integer
/// (invalid type). Unknown keys are deliberately IGNORED (no
/// `deny_unknown_fields`): the asset may gain fields later, so the wire shape
/// is strict about what MUST be present, not about what may appear.
pub(crate) fn parse_manifest(text: &str) -> Result<ReleaseManifest, UpdateError> {
    serde_saphyr::from_str::<ReleaseManifest>(text)
        .map_err(|err| UpdateError::Parse(err.to_string()))
}

/// The `release.yaml` target of the platform this binary ships as, `None`
/// when no artifact is published for it. Windows returns
/// `x86_64-pc-windows-msvc` even in a local MinGW `-gnu` dev build: the
/// artifact `release.yml` publishes is MSVC-built (AGENTS.md release
/// delivery), so the download target must follow the SHIPPED artifact, not
/// the local dev toolchain. Linux x86_64 matches the shipped gnu target;
/// ARM64 is deferred and maps to `None`.
#[cfg(all(target_os = "windows", target_arch = "x86_64"))]
pub(crate) fn platform_file_type() -> Option<&'static str> {
    Some("x86_64-pc-windows-msvc")
}

/// Linux counterpart of [`platform_file_type`].
#[cfg(all(target_os = "linux", target_arch = "x86_64"))]
pub(crate) fn platform_file_type() -> Option<&'static str> {
    Some("x86_64-unknown-linux-gnu")
}

/// Any other OS/arch: `release.yml` publishes no artifact for it, so an
/// update can never be offered.
#[cfg(not(any(
    all(target_os = "windows", target_arch = "x86_64"),
    all(target_os = "linux", target_arch = "x86_64"),
)))]
pub(crate) fn platform_file_type() -> Option<&'static str> {
    None
}

/// Picks the manifest entry for `file_type`. Failure mode:
/// [`UpdateError::NoFileForTarget`] when the manifest carries no such entry.
pub(crate) fn select_file<'a>(
    manifest: &'a ReleaseManifest,
    file_type: &str,
) -> Result<&'a ReleaseFile, UpdateError> {
    manifest
        .files
        .iter()
        .find(|file| file.file_type == file_type)
        .ok_or_else(|| UpdateError::NoFileForTarget(file_type.to_owned()))
}

/// The running build as the update decision sees it: `version` is the
/// About-dialog version string (`about::version_with_dev`, so dev builds carry
/// the `-dev` suffix), `build_time` is shadow-rs `BUILD_TIME_3339` (UTC RFC
/// 3339), `short_commit` is shadow-rs `SHORT_COMMIT`. The decision takes
/// these as injected values, so unit tests never read the embedded constants.
/// `short_commit` returned as a decision input by the hotfix 2026-11-12: it
/// SUPPRESSES the date trigger when the manifest carries the same commit
/// (it never ADDS an "update available" — an unequal sha triggers nothing).
#[derive(Debug, Clone)]
pub(crate) struct BuildInfo {
    pub(crate) version: String,
    pub(crate) build_time: String,
    pub(crate) short_commit: String,
}

impl BuildInfo {
    /// Dev builds (version ending in `-dev`) check for updates on the same
    /// terms as release builds (spec §4.7, stage 11 sub-item 1): the `-dev`
    /// suffix is stripped before the version comparison, so it never makes
    /// the strings spuriously unequal. Callers pass this to state the build
    /// kind at the call site (`main::should_check_at_startup`).
    pub(crate) fn is_dev(&self) -> bool {
        self.version.ends_with("-dev")
    }
}

/// Snapshot of the current build from the embedded shadow-rs constants, for
/// the Stage 7 wiring. shadow-rs leaves build fields empty when the data is
/// unavailable; [`decide_update`] then falls back to the version comparison
/// (and the sha guard reads as inconclusive on empty values).
pub(crate) fn current_build() -> BuildInfo {
    BuildInfo {
        version: crate::about::version_with_dev(crate::build::PKG_VERSION, crate::build::TAG),
        build_time: crate::build::BUILD_TIME_3339.to_owned(),
        short_commit: crate::build::SHORT_COMMIT.to_owned(),
    }
}

/// Update-available rule (spec §4.7, stage 11 sub-item 1): an update exists
/// when the published **release date is newer than the local build time** OR
/// the published **version is higher than the local version**. Hotfix
/// 2026-11-12: when the manifest's `commit_sha` names the SAME commit as the
/// local build ([`commit_matches`]), the DATE trigger is suppressed entirely —
/// `releaseDate` is a packaging timestamp, so CI re-packaging the same commit
/// produces a later date than the local build and used to announce a phantom
/// update. Equal shas never offer an update; an unequal sha triggers nothing
/// by itself. The version trigger keeps its semantics under the guard.
/// The rule applies to release builds AND `-dev` builds alike — the old
/// dev-only sha comparison is gone; the `-dev` suffix is stripped from the
/// local version before comparing so a dev build never reads as unequal.
///
/// Both timestamps are compared as Unix seconds ([`parse_rfc3339_epoch_seconds`]:
/// fractional seconds truncated, UTC offsets applied, so `14:29:09.928+03:00`
/// and `11:29:09.928Z` are the same instant). Failure mode: an unparseable
/// `releaseDate` → [`UpdateError::Parse`] naming the offending value — never
/// "update available"; an unparseable date is not read at all when the shas
/// match (there is nothing to compare). When the embedded build time is empty
/// or unparseable (shadow-rs can leave build fields empty), the date
/// comparison is skipped and only the version comparison decides: dates can
/// NEVER infer an update there.
///
/// Accepted tradeoff (user decision): a newer release date triggers an update
/// even when the manifest version is LOWER than the local version — the
/// dialog then offers the older nightly/prerelease as the "update".
pub(crate) fn decide_update(
    manifest: &ReleaseManifest,
    build: &BuildInfo,
) -> Result<bool, UpdateError> {
    // Hotfix 2026-11-12: same commit → nothing newer to install, the date is
    // not a signal; the version comparison below still decides on its own.
    if !commit_matches(&build.short_commit, &manifest.commit_sha) {
        let release_seconds = parse_rfc3339_epoch_seconds(&manifest.release_date)?;
        // An empty/unparseable embedded build time skips the date comparison;
        // only the version can decide then (dates never infer an update there).
        let build_seconds = parse_rfc3339_epoch_seconds(&build.build_time).ok();
        if let Some(build_seconds) = build_seconds
            && release_seconds > build_seconds
        {
            return Ok(true);
        }
    }
    Ok(version_higher(&manifest.version, &build.version))
}

/// Whether the manifest's `commit_sha` names the same commit as the local
/// build. Abbreviation lengths differ by source — `git rev-parse --short`
/// (what CI writes into the manifest) vs shadow-rs `SHORT_COMMIT` — so a
/// prefix of either side matches, case-insensitively (hex case is a wire
/// artifact). An empty value on either side is INCONCLUSIVE: missing git
/// data must never read as a match, so the date rule keeps applying.
fn commit_matches(local_sha: &str, release_sha: &str) -> bool {
    if local_sha.is_empty() || release_sha.is_empty() {
        return false;
    }
    // Short hex strings (7-40 chars): lowercasing is cheaper than a
    // case-insensitive prefix helper and keeps both directions symmetric.
    let local = local_sha.to_ascii_lowercase();
    let release = release_sha.to_ascii_lowercase();
    local.starts_with(&release) || release.starts_with(&local)
}

/// `major.minor.patch` parsed as three integer segments: missing trailing
/// segments count as 0 (`0.1` == `0.1.0`); more than three segments or a
/// non-numeric/empty segment returns `None` (inconclusive).
fn version_segments(version: &str) -> Option<[u64; 3]> {
    let mut segments = [0u64; 3];
    for (index, segment) in version.split('.').enumerate() {
        if index >= 3 || segment.is_empty() {
            return None;
        }
        segments[index] = segment.parse::<u64>().ok()?;
    }
    Some(segments)
}

/// Whether the release version is higher than the local one, numerically
/// (`0.10.0` > `0.9.0`, never lexicographic). The `-dev` suffix is stripped
/// from the local version first. A garbage segment on either side makes the
/// comparison inconclusive → `false`, never a panic.
fn version_higher(release: &str, local: &str) -> bool {
    let local_base = local.strip_suffix("-dev").unwrap_or(local);
    match (version_segments(release), version_segments(local_base)) {
        (Some(release), Some(local)) => release > local,
        _ => false,
    }
}

/// Hand-written RFC 3339 parser → Unix epoch seconds: `YYYY-MM-DDTHH:MM:SS`
/// with optional fractional seconds (TRUNCATED) and zone `Z`, `±HH:MM`, or no
/// zone (read as UTC — embedded `BUILD_TIME_3339` carries no offset). Proleptic
/// Gregorian via Howard Hinnant's era formula [`days_from_civil`]; no
/// leap-second handling (`:60` is rejected) and no new dependency (std only).
/// Calendar day is accepted in `1..=31` without month-length validation — the
/// comparison only needs a monotonic instant, not calendar strictness.
/// Failure mode: [`UpdateError::Parse`] naming the offending value for
/// anything that is not a timestamp shape (month `0..=12`, `HH:MM:SS` within
/// `23:59:59`, offsets within `±23:59`).
pub(crate) fn parse_rfc3339_epoch_seconds(text: &str) -> Result<i64, UpdateError> {
    let invalid =
        |reason: &str| UpdateError::Parse(format!("invalid release date {text:?}: {reason}"));

    let Some((date, time)) = text.split_once('T') else {
        return Err(invalid("expected YYYY-MM-DDTHH:MM[:fraction][Z|±HH:MM]"));
    };
    let (year, month, day) =
        parse_civil_date(date).ok_or_else(|| invalid("malformed calendar date"))?;

    // Zone suffix: exactly 6 chars `±HH:MM` at the end, `Z`, or absent
    // (embedded `BUILD_TIME_3339` carries no offset → UTC by convention).
    let (clock, offset_seconds) =
        if time.len() >= 7 && matches!(time.as_bytes()[time.len() - 6], b'+' | b'-') {
            match parse_zone_offset(&time[time.len() - 6..]) {
                Some(seconds) => (&time[..time.len() - 6], seconds),
                None => return Err(invalid("malformed UTC offset")),
            }
        } else if let Some(clock) = time.strip_suffix('Z') {
            (clock, 0)
        } else {
            (time, 0)
        };

    let seconds_of_day =
        parse_seconds_of_day(clock).ok_or_else(|| invalid("malformed time of day"))?;
    Ok(days_from_civil(year, month, day) * 86_400 + seconds_of_day - offset_seconds)
}

/// `YYYY-MM-DD` → (year, month, day); month `1..=12`, day `1..=31`.
fn parse_civil_date(date: &str) -> Option<(i64, u32, u32)> {
    let mut fields = date.split('-');
    let year: i64 = fields.next()?.parse().ok()?;
    let month: u32 = fields.next()?.parse().ok()?;
    let day: u32 = fields.next()?.parse().ok()?;
    if fields.next().is_some() || month == 0 || month > 12 || day == 0 || day > 31 {
        return None;
    }
    Some((year, month, day))
}

/// `HH:MM:SS[.fraction]` → whole seconds of the day; fractions must be all
/// digits and are dropped (truncated). `60` seconds (leap second) rejected.
fn parse_seconds_of_day(clock: &str) -> Option<i64> {
    let mut fields = clock.split(':');
    let hours: u32 = fields.next()?.parse().ok()?;
    let minutes: u32 = fields.next()?.parse().ok()?;
    let seconds_field = fields.next()?;
    let (seconds, fraction) = match seconds_field.split_once('.') {
        Some((seconds, fraction)) => (seconds, Some(fraction)),
        None => (seconds_field, None),
    };
    let seconds: u32 = seconds.parse().ok()?;
    if let Some(fraction) = fraction
        && !fraction.bytes().all(|byte| byte.is_ascii_digit())
    {
        return None;
    }
    if fields.next().is_some() || hours > 23 || minutes > 59 || seconds > 59 {
        return None;
    }
    Some(i64::from(hours) * 3600 + i64::from(minutes) * 60 + i64::from(seconds))
}

/// `±HH:MM` UTC offset → seconds (sign applied), hours `<= 23`, minutes `<= 59`.
fn parse_zone_offset(zone: &str) -> Option<i64> {
    let (sign_char, rest) = zone.split_at(1);
    let sign: i64 = match sign_char {
        "+" => 1,
        "-" => -1,
        _ => return None,
    };
    let (hours, minutes) = rest.split_once(':')?;
    let hours: u32 = hours.parse().ok()?;
    let minutes: u32 = minutes.parse().ok()?;
    if hours > 23 || minutes > 59 {
        return None;
    }
    Some(sign * (i64::from(hours) * 3600 + i64::from(minutes) * 60))
}

/// Days since the Unix epoch (1970-01-01) for a civil date in the proleptic
/// Gregorian calendar — Howard Hinnant's `days_from_civil` era formula: the
/// year is shifted so March starts the era, 400-year eras of 146097 days
/// absorb the century/leap rules (`/4 − /100`, years divisible by 400 leap),
/// and the epoch anchor `-719468` maps back to Unix seconds. Exact over the
/// whole `i64` year range, no loop.
fn days_from_civil(year: i64, month: u32, day: u32) -> i64 {
    let era_year = if month <= 2 { year - 1 } else { year };
    let era = era_year.div_euclid(400);
    let year_of_era = era_year - era * 400; // [0, 399]
    let day_of_year = (153 * i64::from(if month > 2 { month - 3 } else { month + 9 }) + 2) / 5
        + i64::from(day)
        - 1;
    let day_of_era = year_of_era * 365 + year_of_era / 4 - year_of_era / 100 + day_of_year;
    era * 146_097 + day_of_era - 719_468
}

/// The next check instant for `interval`: `None` for the `Never` setting (a
/// `None` interval), `Some(now + interval)` otherwise. Overflow of `Instant`
/// folds to `None` — unreachable with a real clock, kept so the scheduler
/// never panics.
pub(crate) fn next_check_deadline(now: Instant, interval: Option<Duration>) -> Option<Instant> {
    interval.and_then(|interval| now.checked_add(interval))
}

/// The metadata download URL for a channel.
pub(crate) fn manifest_url(channel: config::UpdateChannel) -> &'static str {
    match channel {
        config::UpdateChannel::Stable => STABLE_MANIFEST_URL,
        config::UpdateChannel::Nightly => NIGHTLY_MANIFEST_URL,
    }
}

/// Blocking GET of the metadata asset. Failure modes: [`UpdateError::Fetch`]
/// on a transport/TLS/timeout/body error, [`UpdateError::HttpStatus`] on any
/// non-2xx status (redirects are followed by default, so the status is the
/// FINAL one). Never panics. Not exercised by unit tests — no network there.
pub(crate) fn fetch_manifest_text(url: &str) -> Result<String, UpdateError> {
    let agent = ureq::Agent::new_with_config(
        ureq::Agent::config_builder()
            .timeout_global(Some(FETCH_TIMEOUT))
            .user_agent(format!("virshot/{}", crate::build::PKG_VERSION))
            .max_redirects(10)
            .save_redirect_history(true)
            .http_status_as_error(false) // non-2xx is data: read status, never panic
            .build(),
    );

    let mut response = agent
        .get(url)
        .call()
        .map_err(|err| UpdateError::Fetch(err.to_string()))?;

    let status = response.status();
    if !status.is_success() {
        return Err(UpdateError::HttpStatus(status.into()));
    }

    response
        .body_mut()
        .read_to_string()
        .map_err(|err| UpdateError::Fetch(err.to_string()))
}

/// What a background check produced, sent to the GUI over the hand-off
/// channel. A failure is an outcome like any other: the app keeps running.
#[derive(Debug)]
pub(crate) enum CheckOutcome {
    Updated(UpdateInfo),
    UpToDate,
    Failed(UpdateError),
}

/// The data the GUI and Stage 4 install need: summary for the update dialog
/// plus the selected archive for download. `Clone` is justified: the GUI
/// keeps one copy in app state and copies short fields into toast/dialog text.
#[derive(Debug, Clone)]
pub(crate) struct UpdateInfo {
    pub(crate) version: String,
    pub(crate) release_date: String,
    pub(crate) commit_sha: String,
    pub(crate) archive_url: String,
    /// Base64 of the raw 64-byte sha512 digest of the archive asset.
    pub(crate) sha512: String,
    /// Archive size in bytes, for download accounting.
    pub(crate) size: u64,
}

/// The check pipeline, pure behind the `fetch` seam (tests inject a fake
/// fetcher; production passes [`fetch_manifest_text`]). Never panics: every
/// failure becomes a [`CheckOutcome::Failed`]. A dev build checks the same
/// way a release build does — the fetch happens, and [`decide_update`]
/// applies the date/version rule (§4.7, stage 11 sub-item 1), including its
/// `Parse` failure for an unparseable release date.
pub(crate) fn run_check(
    channel: config::UpdateChannel,
    build: &BuildInfo,
    fetch: impl Fn(&str) -> Result<String, UpdateError>,
) -> CheckOutcome {
    let text = match fetch(manifest_url(channel)) {
        Ok(text) => text,
        Err(err) => return CheckOutcome::Failed(err),
    };
    let manifest = match parse_manifest(&text) {
        Ok(manifest) => manifest,
        Err(err) => return CheckOutcome::Failed(err),
    };

    let Some(file_type) = platform_file_type() else {
        let target = format!("{}-{}", std::env::consts::ARCH, std::env::consts::OS);
        return CheckOutcome::Failed(UpdateError::NoFileForTarget(target));
    };
    let file = match select_file(&manifest, file_type) {
        Ok(file) => file,
        Err(err) => return CheckOutcome::Failed(err),
    };

    match decide_update(&manifest, build) {
        Ok(false) => return CheckOutcome::UpToDate,
        Ok(true) => {}
        Err(err) => return CheckOutcome::Failed(err),
    }

    // Owned copies: `UpdateInfo` crosses the channel and must outlive the
    // borrowed manifest entry it was read from.
    let archive_url = file.url.clone();
    let sha512 = file.sha512.clone();
    let size = file.size;

    CheckOutcome::Updated(UpdateInfo {
        version: manifest.version,
        release_date: manifest.release_date,
        commit_sha: manifest.commit_sha,
        archive_url,
        sha512,
        size,
    })
}

/// Spawns ONE plain `std::thread` that runs [`run_check`] and delivers exactly
/// one [`CheckOutcome`] to `sender`; the thread never panics (`run_check` is
/// total). If the receiver is gone (app shutdown), the send error is ignored:
/// there is nowhere left to report. `fetch` is the seam — production passes
/// [`fetch_manifest_text`], tests pass a fake so no network is performed.
pub(crate) fn spawn_check(
    channel: config::UpdateChannel,
    build: BuildInfo,
    sender: mpsc::Sender<CheckOutcome>,
    fetch: impl Fn(&str) -> Result<String, UpdateError> + Send + 'static,
) {
    std::thread::spawn(move || {
        let outcome = run_check(channel, &build, fetch);
        let _ = sender.send(outcome);
    });
}

#[cfg(test)]
#[path = "update.tests.rs"]
mod tests;
